mapper.select:
SELECT v.id, v.db_name AS dbName, v.vector_db_type AS vectorDbType, v.host, v.port, v.database_name AS databaseName, v.collection_name AS collectionName, v.embedding_dimension AS embeddingDimension, v.status, v.remark FROM bedrock_ai_vector_db v WHERE v.is_deleted = 0
AND v.db_name LIKE concat('%', #{param.dbName}, '%')
AND v.vector_db_type = #{param.vectorDbType}
AND v.status = #{param.status}
ORDER BY v.create_time DESC
